Here's a self-contained mortgage calculator with sliders for loan amount, term, and interest rate — the monthly payment and totals update live.

:::intelligent-ui-html{v="1"}
<div class="mc">
  <div class="slider-group">
    <label>Loan amount: <strong id="amountLabel">$300,000</strong></label>
    <input id="amount" type="range" min="50000" max="1000000" step="5000" value="300000" />
  </div>
  <div class="slider-group">
    <label>Loan term: <strong id="yearsLabel">30 years</strong></label>
    <input id="years" type="range" min="1" max="30" step="1" value="30" />
  </div>
  <div class="slider-group">
    <label>Interest rate: <strong id="rateLabel">6.00%</strong></label>
    <input id="rate" type="range" min="2" max="12" step="0.1" value="6.0" />
  </div>
  <div class="results">
    <div class="result primary">
      <div class="result-label">Monthly payment</div>
      <div class="result-value" id="monthly">$0</div>
    </div>
    <div class="result">
      <div class="result-label">Total payments</div>
      <div class="result-value" id="total">$0</div>
    </div>
    <div class="result">
      <div class="result-label">Total interest</div>
      <div class="result-value" id="interest">$0</div>
    </div>
  </div>
</div>
<style>
  .mc { display: flex; flex-direction: column; gap: 1.25rem; padding: 0.5rem; color: var(--viz-text); font-family: inherit; }
  .slider-group { display: flex; flex-direction: column; gap: 0.35rem; }
  .slider-group label { font-size: 0.9rem; color: var(--viz-muted); }
  .slider-group label strong { color: var(--viz-text); font-weight: 700; }
  input[type="range"] { width: 100%; accent-color: var(--viz-accent); cursor: pointer; }
  .results { display: grid; grid-template-columns: repeat(3, 1fr); gap: 0.75rem; margin-top: 0.5rem; }
  .result { background: var(--viz-card); border: 1px solid var(--viz-border); border-radius: 10px; padding: 0.85rem 1rem; }
  .result.primary { border-color: var(--viz-accent); }
  .result-label { font-size: 0.75rem; color: var(--viz-muted); margin-bottom: 0.35rem; text-transform: uppercase; letter-spacing: 0.04em; }
  .result-value { font-size: 1.25rem; font-weight: 700; color: var(--viz-text); }
  .result.primary .result-value { color: var(--viz-accent); }
  @media (max-width: 600px) { .results { grid-template-columns: 1fr; } }
</style>
<script>
  const amount = document.getElementById('amount');
  const years = document.getElementById('years');
  const rate = document.getElementById('rate');
  const fmt = (n) => '$' + Math.round(n).toLocaleString('en-US');
  function update() {
    const P = parseFloat(amount.value);
    const y = parseInt(years.value, 10);
    const r = parseFloat(rate.value) / 100 / 12;
    const n = y * 12;
    const monthly = r > 0 ? (P * r * Math.pow(1+r, n)) / (Math.pow(1+r,n)-1) : P/n;
    const total = monthly * n;
    const interest = total - P;
    document.getElementById('amountLabel').textContent = fmt(P);
    document.getElementById('yearsLabel').textContent = y + ' years';
    document.getElementById('rateLabel').textContent = parseFloat(rate.value).toFixed(2) + '%';
    document.getElementById('monthly').textContent = fmt(monthly);
    document.getElementById('total').textContent = fmt(total);
    document.getElementById('interest').textContent = fmt(interest);
  }
  amount.addEventListener('input', update);
  years.addEventListener('input', update);
  rate.addEventListener('input', update);
  update();
</script>
:::

Monthly payment is amortized over the term at a fixed rate. Adjust the rate if you want to reflect a current offer.

